    /// <summary>Computed fields of a record; the seed loader uses it like the endpoints do.</summary>
    public static void Compute(object item, TimeProvider time)
    {
        switch (item)
        {
            case Driver record: ComputeDriver(record, time); break;
            case GeoPoint record: ComputeGeoPoint(record, time); break;
            case Notification record: ComputeNotification(record, time); break;
            case NotificationType record: ComputeNotificationType(record, time); break;
            case ParkingEvent record: ComputeParkingEvent(record, time); break;
            case ParkingEventType record: ComputeParkingEventType(record, time); break;
            case ParkingSession record: ComputeParkingSession(record, time); break;
            case ParkingSessionStatus record: ComputeParkingSessionStatus(record, time); break;
            case ParkingZone record: ComputeParkingZone(record, time); break;
            case Route record: ComputeRoute(record, time); break;
            case Tariff record: ComputeTariff(record, time); break;
            case TariffPeriod record: ComputeTariffPeriod(record, time); break;
            case Vehicle record: ComputeVehicle(record, time); break;
            case VehicleStatus record: ComputeVehicleStatus(record, time); break;
            case VehicleType record: ComputeVehicleType(record, time); break;
            case WorkObject record: ComputeWorkObject(record, time); break;
            case ZoneState record: ComputeZoneState(record, time); break;
        }
    }

