    private static IResult? ApplyConfirmParkingSession(AppDbContext db, ParkingSession item, ConfirmParkingSession cmd, TimeProvider time)
    {
        var moved = false;
        if (!moved && (item.Status == ParkingSessionState.Created))
        {
            item.Status = ParkingSessionState.Active;
            DomainEvents.Raise(db, "ParkingSessionConfirmedSession", item, item.Id, time);
            moved = true;
        }
        return moved ? null : Results.Problem(title: "transition", statusCode: StatusCodes.Status409Conflict);
    }

    private static IResult? ApplyEndParkingSession(AppDbContext db, ParkingSession item, EndParkingSession cmd, TimeProvider time)
    {
        var moved = false;
        if (!moved && (item.Status == ParkingSessionState.Active))
        {
            item.Status = ParkingSessionState.Completed;
            DomainEvents.Raise(db, "ParkingSessionEndedSessionByDriver", item, item.Id, time);
            moved = true;
        }
        if (!moved && (item.Status == ParkingSessionState.WarningSent))
        {
            item.Status = ParkingSessionState.Completed;
            DomainEvents.Raise(db, "ParkingSessionEndedSessionByDriverAfterWarning", item, item.Id, time);
            moved = true;
        }
        if (!moved && (item.Status == ParkingSessionState.Expired))
        {
            item.Status = ParkingSessionState.Completed;
            DomainEvents.Raise(db, "ParkingSessionEndedExpiredSessionByDriver", item, item.Id, time);
            moved = true;
        }
        return moved ? null : Results.Problem(title: "transition", statusCode: StatusCodes.Status409Conflict);
    }

