    private static IResult? ApplyRenewParkingSession(AppDbContext db, ParkingSession item, RenewParkingSession cmd, TimeProvider time)
    {
        var moved = false;
        if (!moved && (item.Status == ParkingSessionState.WarningSent))
        {
            item.Status = ParkingSessionState.Active;
            DomainEvents.Raise(db, "ParkingSessionRenewedSessionFromWarning", item, item.Id, time);
            moved = true;
        }
        if (!moved && (item.Status == ParkingSessionState.Expired))
        {
            item.Status = ParkingSessionState.Active;
            DomainEvents.Raise(db, "ParkingSessionRenewedExpiredSession", item, item.Id, time);
            moved = true;
        }
        return moved ? null : Results.Problem(title: "transition", statusCode: StatusCodes.Status409Conflict);
    }

